      "title": "Job search experiences and language requirements",
      "claims": [
        {
          "text": "P3 applied to about 100 jobs and received 3 interview invitations",
          "evidence": [21]
        },
        {
          "text": "P3’s interview conversion rate is highest for vacancies requiring a conversation",
          "evidence": [20]
        },
        {
          "text": "P3 found a job within 2 months after moving abroad",
          "evidence": [17]
        },
        {
          "text": "P3 recommends searching for jobs on LinkedIn",
          "evidence": [18]
